    out={}
    for i in range(6):
        out=padd(out,pmul(D,derivative(N[i],i)))
        out=padd(out,pmul(N[i],derivative(D,i)),-1)
    return out

def reduce(v,basis,insert=False,comb=None):
    """Sparse exact column elimination, optionally tracking combinations."""
    while v:
        k=min(v);c=v[k]
        if k not in basis:
            if not insert:return v
            basis[k]=({i:e/c for i,e in v.items()},None if comb is None else {i:e/c for i,e in comb.items()})
            return None
        other,other_comb=basis[k]
        for i,e in other.items():
            z=v.get(i,Q(0))-c*e
            if z:v[i]=z
            elif i in v:del v[i]
        if comb is not None:
            for i,e in other_comb.items():
                z=comb.get(i,Q(0))-c*e
                if z:comb[i]=z
                elif i in comb:del comb[i]
    return {} if comb is None else comb

import argparse
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--scan-basis',action='store_true',help='also test the 109 individual E1 basis denominators')
args=parser.parse_args()
started=time.time()

# Generate the complete E1 denominator space at d=6, N_i degree 7.
rows={u:i for i,u in enumerate(monomials(12))}
e1basis={};labels=[];denominator_pairs=[];numerator_nullity=0
for i in range(6):
    for u in monomials(7):
        k=len(labels);labels.append(('N',i,u))
        col={rows[add(u,v)]:c for v,c in partials[i].items()}
        null=reduce(col,e1basis,True,{k:Q(1)})
        if null is not None:numerator_nullity+=1
assert len(e1basis)==4437 and numerator_nullity==315
jbasis=e1basis.copy()
for u in monomials(6):
    k=len(labels);labels.append(('D',u))
    col={rows[add(u,v)]:c for v,c in A.items()}
    null=reduce(col,e1basis,True,{k:Q(1)})
    if null is not None:
        D={};N=[{} for _ in range(6)]
        for ix,c in null.items():
            item=labels[ix]
            if item[0]=='D':D[item[1]]=c
            else:N[item[1]][item[2]]=-c
        assert D and directional(N)==pmul(A,D)
        denominator_pairs.append((D,N))
assert len(e1basis)==4790 and len(denominator_pairs)==109
Ds=[pair[0] for pair in denominator_pairs];Ns=[pair[1] for pair in denominator_pairs]
print('Complete E1: 4752 numerator columns, rank4437, kernel315; 462 denominator columns, augmented rank4790; denominator dimension109.')

# Directly verify that all N-only fibres are spanned by 315 quadratic-
# coefficient Koszul tuples; no regular-sequence assumption is needed.
mons7=list(monomials(7));index7={u:i for i,u in enumerate(mons7)}
koszul_span={};koszul=[]
for i in range(6):
    for j in range(i+1,6):
        for u in monomials(2):
